create table if not exists public.digital_page_products (id uuid primary key default gen_random_uuid(),page_type text not null check (page_type in ('PORTFOLIO','MENU')),code text not null unique,name_ar text not null,description_ar text,price numeric(12,2) not null check (price >= 0),currency text not null default 'EGP',duration_days integer,features jsonb not null default '[]'::jsonb,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index if not exists digital_page_products_active_idx on public.digital_page_products(page_type,active);
create table if not exists public.digital_page_orders (id uuid primary key default gen_random_uuid(),user_id uuid not null,target_business_id uuid references public.businesses(id) on delete set null,product_id uuid not null references public.digital_page_products(id),page_type text not null check (page_type in ('PORTFOLIO','MENU')),title text not null,slug text,amount numeric(12,2) not null check (amount >= 0),currency text not null default 'EGP',pricing_hash text not null,idempotency_key text not null,payment_status text not null default 'PENDING' check (payment_status in ('PENDING','PAID','FAILED','REFUNDED','CANCELLED')),fulfillment_status text not null default 'REQUESTED' check (fulfillment_status in ('REQUESTED','IN_REVIEW','IN_PROGRESS','PUBLISHED','REJECTED','CANCELLED')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,idempotency_key)); create index if not exists digital_page_orders_user_idx on public.digital_page_orders(user_id,created_at desc); create index if not exists digital_page_orders_business_idx on public.digital_page_orders(target_business_id,created_at desc);
alter table public.digital_page_products enable row level security; alter table public.digital_page_orders enable row level security;
drop policy if exists digital_page_products_public_read on public.digital_page_products; create policy digital_page_products_public_read on public.digital_page_products for select to anon,authenticated using (active=true);
drop policy if exists digital_page_products_admin_write on public.digital_page_products; create policy digital_page_products_admin_write on public.digital_page_products for all to authenticated using (exists(select 1 from public.user_memberships m where m.user_id=auth.uid() and m.status='ACTIVE' and m.role in ('SUPER_ADMIN','ADMIN'))) with check (exists(select 1 from public.user_memberships m where m.user_id=auth.uid() and m.status='ACTIVE' and m.role in ('SUPER_ADMIN','ADMIN')));
drop policy if exists digital_page_orders_owner_read on public.digital_page_orders; create policy digital_page_orders_owner_read on public.digital_page_orders for select to authenticated using (user_id=auth.uid());
insert into public.digital_page_products(page_type,code,name_ar,description_ar,price,currency,duration_days,features) values ('PORTFOLIO','PORTFOLIO_START','Portfolio أساسي','صفحة شخصية احترافية قابلة للمشاركة مع نبذة وخدمات وأعمال ووسائل تواصل.',499,'EGP',365,'["صفحة عامة","نبذة","الخدمات","الأعمال","وسائل التواصل","رابط مخصص"]'::jsonb),('PORTFOLIO','PORTFOLIO_PRO','Portfolio احترافي','صفحة شخصية متقدمة مع أقسام موسعة وSEO ووسائط وعرض أعمال احترافي.',899,'EGP',365,'["كل الأساسي","أقسام موسعة","معرض أعمال","SEO","وسائط","إحصاءات أساسية"]'::jsonb),('MENU','MENU_START','Menu أساسي','صفحة قائمة رقمية للمطعم أو الكافيه أو مقدم الخدمة.',399,'EGP',365,'["صفحة Menu","تصنيفات","عناصر وأسعار","رابط مشاركة","QR"]'::jsonb),('MENU','MENU_PRO','Menu احترافي','صفحة Menu متقدمة مع أقسام وصور وSEO ورابط مشاركة وQR.',799,'EGP',365,'["كل الأساسي","صور","خيارات وأقسام","SEO","QR","إحصاءات أساسية"]'::jsonb) on conflict(code) do update set name_ar=excluded.name_ar,description_ar=excluded.description_ar,price=excluded.price,currency=excluded.currency,duration_days=excluded.duration_days,features=excluded.features,active=excluded.active,updated_at=now();
revoke all on public.digital_page_orders from anon; revoke insert,update,delete on public.digital_page_orders from authenticated;